"""Allocated-range reporting for sink files."""

import os

from . import _winapi as w
from ._core import Handle, normalise_ranges, os_error, reject_non_file


def _ranges_windows(path):
    with Handle(path, w.GENERIC_READ, w.OPEN_EXISTING) as handle:
        size = handle.size()
        if size == 0:
            return []
        raw = handle.query_allocated_ranges(size)
    return normalise_ranges(raw, size)


def _ranges_posix(path):
    # Not part of the supported platform matrix; kept so that the smoke tests
    # can be run off Windows during development.
    size = os.path.getsize(path)
    if size == 0:
        return []
    seek_data = getattr(os, "SEEK_DATA", None)
    seek_hole = getattr(os, "SEEK_HOLE", None)
    if seek_data is None or seek_hole is None:
        return [(0, size)]
    found = []
    fd = os.open(path, os.O_RDONLY)
    try:
        offset = 0
        while offset < size:
            try:
                start = os.lseek(fd, offset, seek_data)
            except OSError:
                break
            if start >= size:
                break
            end = os.lseek(fd, start, seek_hole)
            if end <= start:  # pragma: no cover - defensive
                break
            found.append((start, min(end, size) - start))
            offset = end
    finally:
        os.close(fd)
    return normalise_ranges(found, size)


def allocated_ranges(path):
    """Return ``[(offset, length), ...]`` of the byte ranges backed by clusters.

    The transfer layer uses this to decide which parts of a sink still have to
    be fetched: a range that is reported here is really on disk, everything
    else is a hole that still needs data.  The list is ordered by ``offset``,
    the ranges never overlap and every range lies inside the file's logical
    length.

    A file that is nothing but holes reports an empty list; a dense file
    reports a single range covering its whole length.
    """
    path = os.fspath(path)
    reject_non_file(path, require_existing=True)
    if w.is_windows():
        return _ranges_windows(path)
    try:
        return _ranges_posix(path)
    except OSError as exc:
        raise os_error(exc, path) from exc

